var t=`1150-tourtiere`;var i=`world-1150`;var a=`CA`;var r=`northern-america`;var o=4;var s=101;var u={en:`Tourtière`,ua:`Туртьєр`};var d={en:`Tourtière is a dish from Canada prepared with all-purpose flour, ground pork, ground beef, yellow onion. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Туртьєр, страва кухні країни Канада, яку готують із таких продуктів: пшеничне борошно універсальне, свинячий фарш, яловичий фарш, жовта цибуля. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 22 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 22 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:22,i:[[`all-purpose-flour`,450,`g`],[`unsalted-butter`,185,`g`],[`water`,150,`ml`],[`table-salt`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`ground-pork`,550,`g`],[`ground-beef`,350,`g`],[`yellow-onion`,230,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 16 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 16 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:16,i:[[`potato`,300,`g`],[`ground-cinnamon`,4,`g`],[`ground-cloves`,2,`g`],[`beef-stock`,200,`ml`]]},{en:`Layer the already prepared filling and base evenly in the baking dish or pan.`,ua:`Рівномірно викладіть уже підготовлені основу й начинку шарами у форму чи на деко.`,t:[`layered-assembly`],m:10,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 42 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 42 хвилин до готовності.`,t:[`baking`],m:42,i:[]}];var g={slug:t,id:i,country:`CA`,region:r,servings:4,minutes:101,title:u,text:d,steps:l};export{a as country,g as default,i as id,s as minutes,r as region,o as servings,t as slug,l as steps,d as text,u as title};